import SwiftUI
import UIKit

/// The Hợp nhất design tokens. Names match `design/tokens.json`, which is also what
/// Android reads. Colours live in the asset catalog (`Tokens/<name>`) with a light and a
/// dark appearance, generated by `scripts/generate-theme-assets.py`.
enum Theme {
    private static func token(_ name: String) -> Color { Color("Tokens/" + name) }

    static let bg = token("bg")
    static let bgTop = token("bgTop")
    static let surface = token("surface")
    static let sheet = token("sheet")
    static let field = token("field")
    static let ink = token("ink")
    static let muted = token("muted")
    static let hairline = token("hairline")
    static let accent = token("accent")
    static let onAccent = token("onAccent")
    static let protected = token("protected")
    static let protectedText = token("protectedText")
    static let danger = token("danger")
    static let onDanger = token("onDanger")
    static let dangerText = token("dangerText")
    static let warnText = token("warnText")
    static let tagBg = token("tagBg")
    static let tagInk = token("tagInk")
    static let okBg = token("okBg")
    static let okInk = token("okInk")
    static let switchOff = token("switchOff")
    static let shieldCore = token("shieldCore")
    static let highlight = token("highlight")
    static let toastBg = token("toastBg")
    static let toastInk = token("toastInk")
    static let scrim = token("scrim")
    static let glowOn = token("glowOn")
    static let glowOff = token("glowOff")
    static let shadow = token("shadow")
    static let confetti1 = token("confetti1")
    static let confetti2 = token("confetti2")
    static let confetti3 = token("confetti3")
    static let confetti4 = token("confetti4")

    enum Radius {
        static let card: CGFloat = 28
        static let field: CGFloat = 20
        static let sheet: CGFloat = 36
    }

    enum Size {
        static let buttonHeight: CGFloat = 60
        static let touchTarget: CGFloat = 44
    }

    enum Motion {
        /// Spring used for presses, the shield stamp and row changes.
        static let spring = Animation.spring(response: 0.35, dampingFraction: 0.62)
        static let fast = Animation.easeOut(duration: 0.22)
        static let shieldPulse: Double = 2.4
    }

    /// Rounded system font that still follows Dynamic Type.
    static func font(_ style: Font.TextStyle, weight: Font.Weight = .regular) -> Font {
        .system(style, design: .rounded).weight(weight)
    }

    static var backdrop: LinearGradient {
        LinearGradient(stops: [.init(color: bgTop, location: 0), .init(color: bg, location: 0.46)], startPoint: .top, endPoint: .bottom)
    }
}

/// The user's appearance choice. `system` follows the phone.
enum Appearance: String, CaseIterable {
    case system, light, dark

    static let storageKey = "appearance"

    var colorScheme: ColorScheme? {
        switch self {
        case .system: return nil
        case .light: return .light
        case .dark: return .dark
        }
    }
}
